import{H as e,Q as t,ht as n,nt as r,rt as i,tt as a}from"./chunks/framework.Cs5aHXsR.js";import"./chunks/assets.DXlyCrC6.js";var o=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"UltraChess","text":"Documentation","tagline":"A alternate version of Chess for people who want more from their chess set.","image":{"src":"/logoglow.svg","alt":"UltraChess logo"},"actions":[{"theme":"brand","text":"Get Started","link":"/welcome"},{"theme":"alt","text":"Pieces Guide","link":"/pawns"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),s={name:`index.md`};function c(e,o,s,c,l,u){return n(),a(`div`,null,[...o[0]||=[r(`<h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>Ultra Chess is a version of chess that allows pieces to combine with each other to create higher ranked pieces. In UC, it is not uncommon to have 3 rooks and 2 queens at any point of time.</p><p>For example, if a <strong>bishop</strong> (Lvl 2, Value 3) combines with a <strong>pawn</strong> (Lvl 1, Value 1), then those pieces will create a <strong>rook</strong> (Lvl 3, Value 5). These 2 pieces will now move together on the same square, but with rook capabilities. You will learn more about how each piece combines on the following pages through detailed descriptions and examples.</p><p><strong>Disclaimer:</strong> Ultra Chess is just a variation of chess, with all original chess still applying during play unless stated otherwise (e.g. Checking, Mating, Castleing, etc.)</p><h2 id="pieces" tabindex="-1">Pieces <a class="header-anchor" href="#pieces" aria-label="Permalink to “Pieces”">​</a></h2><ul><li><strong><a href="/pawns.html">Pawns</a></strong> = Level 1 (Value 1)</li><li><strong><a href="/knights-bishops.html">Knights/Bishops</a></strong> = Level 2 (Value 3)</li><li><strong><a href="/rooks.html">Rooks</a></strong> = Level 3 (Value 5)</li><li><strong><a href="/queens-ultraqueens.html">Queens</a></strong> = Level 4 (Value 9)</li><li><strong>Ultra Queens</strong> = Level 5 (Value 15)</li></ul><h2 id="example-play" tabindex="-1">Example Play <a class="header-anchor" href="#example-play" aria-label="Permalink to “Example Play”">​</a></h2>`,7),t(`video`,{autoplay:``,muted:``,playsinline:``,width:`30%`,controls:``},[t(`source`,{src:`/assets/video1.COREf799.mp4`,type:`video/mp4`}),i(` Your browser does not support the video tag. `)],-1)]])}var l=e(s,[[`render`,c]]);export{o as __pageData,l as default};